sys_script.script:
(function updateInventoryPosition() {
    var store = current.getValue('store');
    var sku = current.getValue('sku');
    var direction = current.getValue('movement_direction');
    var quantity = parseInt(current.getValue('quantity'), 10);
    var txnNumber = current.getValue('transaction_number');

    gs.info('[Retail Store Assistant] Update Inventory Position: processing transaction ' + txnNumber + ' — store=' + store + ' sku=' + sku + ' direction=' + direction + ' qty=' + quantity);

    // Find the existing Inventory Position for this Store + SKU
    var position = new GlideRecord('x_1945330_retail_0_inv_pos');
    position.addQuery('store', store);
    position.addQuery('sku', sku);
    position.setLimit(1);
    position.query();

    if (!position.next()) {
        gs.info('[Retail Store Assistant] Update Inventory Position: no existing position found for store=' + store + ' sku=' + sku + ' — creating new position');

        // Create a new Inventory Position for this Store + SKU
        var newPos = new GlideRecord('x_1945330_retail_0_inv_pos');
        newPos.initialize();
        newPos.setValue('store', store);
        newPos.setValue('sku', sku);
        newPos.setValue('on_hand', '0');
        newPos.setValue('reserved', '0');
        newPos.setValue('unavailable', '0');
        newPos.setValue('available', '0');
        newPos.setValue('integrity_status', 'normal');
        newPos.insert();

        // Re-query to apply effect
        position = new GlideRecord('x_1945330_retail_0_inv_pos');
        position.addQuery('store', store);
        position.addQuery('sku', sku);
        position.setLimit(1);
        position.query();
        if (!position.next()) {
            gs.error('[Retail Store Assistant] Update Inventory Position: failed to create position for store=' + store + ' sku=' + sku);
            return;
        }

        gs.debug('[Retail Store Assistant] Update Inventory Position: new position created successfully');
    }

    // Apply inventory effect
    var currentOnHand = parseInt(position.getValue('on_hand'), 10) || 0;
    var reserved = parseInt(position.getValue('reserved'), 10) || 0;
    var unavailable = parseInt(position.getValue('unavailable'), 10) || 0;

    var newOnHand;
    if (direction === 'in') {
        newOnHand = currentOnHand + quantity;
    } else {
        newOnHand = currentOnHand - quantity;
    }

    // Recalculate available = on_hand - reserved - unavailable
    var newAvailable = newOnHand - reserved - unavailable;

    // Determine integrity status
    var integrityStatus = 'normal';
    if (newAvailable < 0) {
        integrityStatus = 'reconciliation_required';
        gs.warn('[Retail Store Assistant] Update Inventory Position: negative available detected (' + newAvailable + ') after transaction ' + txnNumber + ', marking reconciliation_required');
    }

    // Update the position
    position.setValue('on_hand', newOnHand.toString());
    position.setValue('available', newAvailable.toString());
    position.setValue('integrity_status', integrityStatus);

    // Update last_recalculated_on with current time
    var now = new GlideDateTime();
    position.setValue('last_recalculated_on', now.getDisplayValue());

    position.update();

    gs.info('[Retail Store Assistant] Update Inventory Position: position updated — on_hand: ' + currentOnHand + ' → ' + newOnHand + ', available: ' + newAvailable);
})();
